const rideSchema = z.object({ quoteId: z.string().min(1), scheduledFor: z.string().datetime().optional(), pickupNotes: z.string().trim().max(500).optional() });
const statusSchema = z.object({ status: z.enum(["DRIVER_ARRIVING","DRIVER_ARRIVED","WAITING","RIDER_VERIFIED","IN_PROGRESS","COMPLETED","CANCELLED"]), reason: z.string().trim().min(3).max(500).optional(), riderPin: z.string().regex(/^\d{4}$/).optional(), actualLocation: z.object({ latitude: z.number().min(-90).max(90), longitude: z.number().min(-180).max(180) }).optional(), forceOutsideDropoff: z.boolean().default(false) }).superRefine((input,ctx)=>{ if(input.status==="CANCELLED"&&!input.reason)ctx.addIssue({code:"custom",path:["reason"],message:"Cancellation reason is required"}); if(input.status==="RIDER_VERIFIED"&&!input.riderPin)ctx.addIssue({code:"custom",path:["riderPin"],message:"Rider PIN is required"}); if(input.status==="COMPLETED"&&!input.actualLocation)ctx.addIssue({code:"custom",path:["actualLocation"],message:"Actual drop-off location is required"}); if(input.status==="COMPLETED"&&input.forceOutsideDropoff&&!input.reason)ctx.addIssue({code:"custom",path:["reason"],message:"A reason is required for an outside-drop-off override"}); });
const driverProfileSchema = z.object({ serviceClasses: z.array(z.enum(["GO","COMFORT","XL"])).min(1).max(3).default(["GO"]), maxPickupDistanceMeters: z.number().int().min(1000).max(30_000).default(DRIVE_DEFAULT_MAX_PICKUP_DISTANCE_METERS), maxPickupEtaSeconds: z.number().int().min(120).max(3600).default(DRIVE_DEFAULT_MAX_PICKUP_ETA_SECONDS), vehicle: z.object({ rideClass:z.enum(["GO","COMFORT","XL"]),make:z.string().trim().min(2).max(80),model:z.string().trim().min(1).max(80),color:z.string().trim().min(2).max(40),plateNumber:z.string().trim().min(3).max(32),capacity:z.number().int().min(1).max(12).default(4) }).optional() });
const driverLocationSchema=z.object({latitude:z.number().min(-90).max(90),longitude:z.number().min(-180).max(180),accuracyMeters:z.number().min(0).max(5000).optional(),online:z.boolean().optional()});
const driverDocumentSchema=z.object({type:z.enum(["DRIVER_LICENCE","VEHICLE_INSURANCE","VEHICLE_INSPECTION","IDENTITY_SUPPORTING"]),assetId:z.string().min(1),documentNumber:z.string().trim().min(2).max(120).optional(),expiresAt:z.string().datetime().optional()});
const fuelPriceSchema=z.object({priceMinorPerLitre:z.number().int().positive().max(10_000_000),referencePriceMinorPerLitre:z.number().int().positive().max(10_000_000).optional(),source:z.string().trim().min(2).max(160),evidenceUrl:z.string().trim().url().refine(value=>value.startsWith("https://"),"An HTTPS evidence URL is required").optional(),effectiveFrom:z.string().datetime().optional(),metadata:z.record(z.string(),z.unknown()).optional()});
const driverTransitions:Record<string,readonly string[]>={DRIVER_ASSIGNED:["DRIVER_ARRIVING"],DRIVER_ARRIVING:["DRIVER_ARRIVED"],DRIVER_ARRIVED:["WAITING","RIDER_VERIFIED"],WAITING:["RIDER_VERIFIED"],RIDER_VERIFIED:["IN_PROGRESS"],IN_PROGRESS:["COMPLETED"],COMPLETED:[],CANCELLED:[]};
