function assertDriverTransition(current:string,next:string){if(!(driverTransitions[current]??[]).includes(next))throw new AppError("CONFLICT",`Cannot transition ride from ${current} to ${next}`,409)}
function quoteContract(q:any):DrivePricingQuoteContract{const snap=q.pricingSnapshot && typeof q.pricingSnapshot==="object" ? q.pricingSnapshot as Record<string,unknown> : {};return{id:q.id,rideClass:q.rideClass,distanceMeters:q.distanceMeters,durationSeconds:q.durationSeconds,etaMinutes:Math.max(2,Math.ceil(q.durationSeconds/60)),baseFareMinor:safeMinor(q.baseFareMinor),distanceFareMinor:safeMinor(q.distanceFareMinor),timeFareMinor:safeMinor(q.timeFareMinor),subtotalMinor:safeMinor(q.subtotalMinor),fuelAdjustmentMinor:safeMinor(q.fuelAdjustmentMinor),demandAdjustmentMinor:safeMinor(q.demandAdjustmentMinor),tollsMinor:safeMinor(q.tollsMinor),feesMinor:safeMinor(q.feesMinor),discountsMinor:safeMinor(q.discountsMinor),surgeBps:q.surgeBps,fuelIndexBps:q.fuelIndexBps,platformFeeBps:q.platformFeeBps,platformFeeMinor:safeMinor(q.platformFeeMinor),driverEarningsMinor:safeMinor(q.driverEarningsMinor),totalMinor:safeMinor(q.totalMinor),currency:q.currency,pricingRuleVersion:q.pricingRuleVersion,expiresAt:q.expiresAt.toISOString(),fuelDisclosure:{status:typeof snap.fuelStatus==="string"?snap.fuelStatus as "CURRENT"|"STALE"|"PENDING_VERIFICATION"|"UNAVAILABLE":"LEGACY",source:typeof snap.fuelSource==="string"?snap.fuelSource:null,evidenceUrl:typeof snap.fuelEvidenceUrl==="string"?snap.fuelEvidenceUrl:null,effectiveFrom:typeof snap.fuelEffectiveFrom==="string"?snap.fuelEffectiveFrom:null,weightBps:typeof snap.fuelWeightBps==="number"?snap.fuelWeightBps:3000,maxAdjustmentBps:typeof snap.maxFuelAdjustmentBps==="number"?snap.maxFuelAdjustmentBps:1200}}}
function rideContract(r:any):DriveRideContract{return{id:r.id,quoteId:r.quoteId,status:r.status,driverUserId:r.driverUserId,paymentMode:r.paymentMode,fareFundingStatus:r.fareFundingStatus,fundedAmountMinor:safeMinor(r.fundedAmountMinor),platformFeeBps:r.platformFeeBps,platformChargeMinor:safeMinor(r.platformChargeMinor),driverEarningsMinor:safeMinor(r.driverEarningsMinor),scheduledFor:r.scheduledFor?.toISOString()??null,searchRadiusMeters:r.searchRadiusMeters,createdAt:r.createdAt.toISOString()}}
function profileContract(p:any):DriveDriverProfileContract{return{userId:p.userId,approvalStatus:p.approvalStatus,availability:p.availability,serviceClasses:p.serviceClasses,walletBalanceMinor:safeMinor(p.walletBalanceMinor),platformDebtMinor:safeMinor(p.platformDebtMinor),maxPickupDistanceMeters:p.maxPickupDistanceMeters,maxPickupEtaSeconds:p.maxPickupEtaSeconds,lastLocationAt:p.lastLocationAt?.toISOString()??null}}
function offerContract(o:any):DriveDispatchOfferContract{return{id:o.id,rideId:o.rideId,status:o.status,pickupDistanceMeters:o.pickupDistanceMeters,pickupEtaSeconds:o.pickupEtaSeconds,searchRadiusMeters:o.searchRadiusMeters,expiresAt:o.expiresAt.toISOString(),quote:quoteContract(o.ride.quote)}}
async function expireOffers(driverUserId:string){const expired=await db.driveDispatchOffer.findMany({where:{driverUserId,status:"OFFERED",expiresAt:{lte:new Date()}},select:{id:true,rideId:true}});for(const o of expired){await db.$transaction(async tx=>{await tx.driveDispatchOffer.updateMany({where:{id:o.id,status:"OFFERED"},data:{status:"EXPIRED",respondedAt:new Date()}});await tx.driveRideEvent.create({data:{rideId:o.rideId,type:"DISPATCH_OFFER_EXPIRED",payload:{driverUserId}}})});await assignNearestDriver(o.rideId)}}

