 app.get("/v1/drive/capabilities",async()=>{const r=await currentDriveRules();return{rideClasses:["GO","COMFORT","XL"],pricing:"SERVER_SNAPSHOT",fareNegotiation:false,nearbyAutoDispatch:true,automaticFuelRegulation:true,fareWalletLock:true,platformFeeBps:DRIVE_PLATFORM_FEE_BPS,driverCancellationFeeBps:DRIVE_DRIVER_CANCEL_FEE_BPS,dropoffViolationFeeBps:DRIVE_DROPOFF_VIOLATION_FEE_BPS,pickupOfferTtlSeconds:DRIVE_OFFER_TTL_SECONDS,callUnlockMeters:r.callUnlockMeters,callUnlockEtaSeconds:r.callUnlockEtaSeconds,maxPickupDistanceMeters:r.maxPickupDistanceMeters,maxPickupEtaSeconds:r.maxPickupEtaSeconds,dropoffGeofenceMeters:r.dropoffGeofenceMeters,requestRequiresBazId:true}});
 app.get("/v1/drive/rides", async request => {
  const auth = await requireAuth(request);
  const query = z.object({ status: z.string().trim().optional(), limit: z.coerce.number().int().min(1).max(100).default(30) }).parse(request.query);
  const rides = await db.driveRide.findMany({
    where: { riderUserId: auth.userId, status: query.status || undefined },
    include: { quote: true, fareHold: true },
    orderBy: { createdAt: "desc" },
    take: query.limit,
  });
  return { rides: rides.map((row) => ({
    ride: rideContract(row),
    pricing: quoteContract(row.quote),
    pickup: row.quote.pickup,
    dropoff: row.quote.dropoff,
    fareHoldStatus: row.fareHold?.status ?? null,
  })) };
 });

 app.post("/v1/drive/pricing",async(request,reply)=>{const input=priceSchema.parse(request.body);if(input.tollsMinor||input.feesMinor||input.discountsMinor)throw new AppError("BAD_REQUEST","Tolls, fees and discounts must be priced from trusted server-side sources; arbitrary client values are disabled",400);const straightDistance=haversineMeters(input.pickup,input.dropoff);if(straightDistance<100||input.distanceMeters<Math.round(straightDistance*.85))throw new AppError("BAD_REQUEST","Estimated route must be consistent with the selected pickup and destination pins",400);const auth=await resolveAuth(request);const rules=await currentDriveRules();const calc=calculateDrivePrice({rideClass:input.rideClass,distanceMeters:input.distanceMeters,durationSeconds:input.durationSeconds,fuelIndexBps:rules.fuelIndexBps,surgeBps:rules.surgeBps,tollsMinor:input.tollsMinor,feesMinor:input.feesMinor,discountsMinor:input.discountsMinor});const quote=await db.drivePricingQuote.create({data:{userId:auth?.userId,pickup:input.pickup as Prisma.InputJsonValue,dropoff:input.dropoff as Prisma.InputJsonValue,rideClass:input.rideClass,distanceMeters:input.distanceMeters,durationSeconds:input.durationSeconds,...calc,fuelPricePerLitreMinor:rules.fuelPricePerLitreMinor,fuelReferencePricePerLitreMinor:rules.fuelReferencePricePerLitreMinor,pricingRuleVersion:DRIVE_PRICING_RULE_VERSION,pricingSnapshot:{region:env.REGION,ruleVersion:DRIVE_PRICING_RULE_VERSION,fuelStatus:rules.fuelStatus,fuelSource:rules.fuelSource,fuelEvidenceUrl:rules.fuelEvidenceUrl,fuelEffectiveFrom:rules.fuelEffectiveFrom,fuelWeightBps:rules.fuelWeightBps,maxFuelAdjustmentBps:rules.fuelMaxAdjustmentBps,fuelIndexBps:rules.fuelIndexBps,surgeBps:rules.surgeBps,platformFeeBps:DRIVE_PLATFORM_FEE_BPS,formula:"base+distance+time+limited-fuel+demand+tolls+fees-discounts"},expiresAt:new Date(Date.now()+5*60_000)}});return reply.code(201).send(quoteContract(quote))});
 app.post("/v1/drive/rides",async(request,reply)=>{const auth=await requireAuth(request);const input=rideSchema.parse(request.body);const key=request.headers["idempotency-key"]?.toString();if(!key)throw new AppError("BAD_REQUEST","Idempotency-Key is required",400);const scheduledFor=input.scheduledFor?new Date(input.scheduledFor):null;if(scheduledFor&&(scheduledFor.getTime()<=Date.now()+5*60_000||scheduledFor.getTime()>Date.now()+90*86400_000))throw new AppError("BAD_REQUEST","Scheduled rides must be between 5 minutes and 90 days from now",400);const result=await withIdempotency<DriveRideRequestResponseContract>({scope:"drive.ride",key,actorId:auth.userId,requestPayload:input,execute:async()=>{const quote=await db.drivePricingQuote.findUnique({where:{id:input.quoteId}});if(!quote||quote.expiresAt<=new Date())throw new AppError("CONFLICT","Drive pricing quote is missing or expired",409);if(quote.userId&&quote.userId!==auth.userId)throw new AppError("FORBIDDEN","Pricing quote belongs to another account",403);const pin=randomInt(1000,10000).toString();const initial=scheduledFor&&scheduledFor.getTime()-Date.now()>20*60_000?"REQUESTED":"MATCHING";const ride=await db.$transaction(async tx=>{const created=await tx.driveRide.create({data:{quoteId:quote.id,riderUserId:auth.userId,status:initial,riderPinHash:sha256Base64Url(pin),scheduledFor,pickupNotes:input.pickupNotes,paymentMode:"WALLET",fareFundingStatus:"UNFUNDED",platformFeeBps:quote.platformFeeBps,platformChargeMinor:quote.platformFeeMinor,driverEarningsMinor:quote.driverEarningsMinor,events:{create:{type:"RIDE_REQUESTED",payload:{scheduledFor:scheduledFor?.toISOString()??null}}}}});await reserveRideFare(tx,{rideId:created.id,riderUserId:auth.userId,amountMinor:quote.totalMinor,currency:quote.currency});const funded=await tx.driveRide.update({where:{id:created.id},data:{fareFundingStatus:"HELD",fundedAmountMinor:quote.totalMinor}});await tx.drivePricingQuote.update({where:{id:quote.id},data:{confirmedAt:new Date()}});await appendOutboxEvent(tx,{aggregateType:"DriveRide",aggregateId:created.id,eventType:"drive.ride.requested",payload:{rideId:created.id,riderUserId:auth.userId,rideClass:quote.rideClass,fareLockedMinor:quote.totalMinor.toString()}});return funded},{isolationLevel:Prisma.TransactionIsolationLevel.Serializable});if(initial==="MATCHING")await assignNearestDriver(ride.id);return{statusCode:201,body:{ride:rideContract(ride),riderPin:pin}}}});return reply.code(result.statusCode).header("x-idempotent-replay",String(result.replayed)).send(result.body)});
 app.get("/v1/drive/rides/:id",async request=>{const auth=await requireAuth(request);const{id}=z.object({id:z.string()}).parse(request.params);const ride=await db.driveRide.findFirst({where:{id,OR:[{riderUserId:auth.userId},{driverUserId:auth.userId}]},include:{quote:true,events:{orderBy:{createdAt:"asc"}},penalties:true}});if(!ride)throw new AppError("NOT_FOUND","Ride not found",404);let driver:any=null;if(ride.driverUserId){const[user,profile]=await Promise.all([db.user.findUnique({where:{id:ride.driverUserId},select:{displayName:true}}),db.driveDriverProfile.findUnique({where:{userId:ride.driverUserId},include:{vehicles:{where:{active:true,status:"APPROVED"},orderBy:{updatedAt:"desc"},take:1}}})]);if(profile){const v=profile.vehicles[0]??null;driver={displayName:user?.displayName?.trim()||"Driver",ratingAverage:profile.ratingAverage===null?null:Number(profile.ratingAverage),ratingCount:profile.ratingCount,vehicle:v?{make:v.make,model:v.model,color:v.color,plateNumber:v.plateNumber,rideClass:v.rideClass,capacity:v.capacity}:null}}}return{ride:rideContract(ride),pricing:quoteContract(ride.quote),driver,events:ride.events.map(e=>({type:e.type,createdAt:e.createdAt.toISOString(),payload:e.payload})),penalties:ride.penalties.map(p=>({type:p.type,rateBps:p.rateBps,amountMinor:safeMinor(p.amountMinor),status:p.status,reason:p.reason}))}});
 app.get("/v1/drive/rides/:id/communication",async request=>{const auth=await requireAuth(request);const{id}=z.object({id:z.string()}).parse(request.params);const ride=await db.driveRide.findFirst({where:{id,OR:[{riderUserId:auth.userId},{driverUserId:auth.userId}]},include:{quote:true}});if(!ride)throw new AppError("NOT_FOUND","Ride not found",404);if(!ride.driverUserId)return{chatAllowed:false,callAllowed:false,maskedCalling:true,reason:"NO_DRIVER_ASSIGNED"};const d=await db.driveDriverProfile.findUnique({where:{userId:ride.driverUserId}});const pickup=pickupPointFromJson(ride.quote.pickup);if(!d||d.currentLatitude===null||d.currentLongitude===null||!pickup)return{chatAllowed:true,callAllowed:false,maskedCalling:true,reason:"DRIVER_NOT_CLOSE_ENOUGH"};const distance=haversineMeters(pickup,{latitude:d.currentLatitude,longitude:d.currentLongitude});const eta=estimatePickupEtaSeconds(distance);const rules=await currentDriveRules();const pre=["DRIVER_ASSIGNED","DRIVER_ARRIVING","DRIVER_ARRIVED","WAITING"].includes(ride.status);const active=["RIDER_VERIFIED","IN_PROGRESS"].includes(ride.status);const callAllowed=active||(pre&&(distance<=rules.callUnlockMeters||eta<=rules.callUnlockEtaSeconds));if(callAllowed&&!ride.callUnlockedAt)await db.driveRide.update({where:{id},data:{callUnlockedAt:new Date()}});return{chatAllowed:pre||active,callAllowed,maskedCalling:true,distanceMeters:distance,etaSeconds:eta}});
 app.patch("/v1/drive/rides/:id/status",async request=>{const auth=await requireAuth(request);const{id}=z.object({id:z.string()}).parse(request.params);const input=statusSchema.parse(request.body);const existing=await db.driveRide.findUnique({where:{id},include:{quote:true,fareHold:true}});if(!existing)throw new AppError("NOT_FOUND","Ride not found",404);const riderCancel=input.status==="CANCELLED"&&existing.riderUserId===auth.userId;if(riderCancel){if(!riderCancellationStates.has(existing.status))throw new AppError("CONFLICT",`Ride cannot be cancelled by the rider while ${existing.status}`,409);const ride=await db.$transaction(async tx=>{const changed=await tx.driveRide.updateMany({where:{id,status:existing.status,riderUserId:auth.userId},data:{status:"CANCELLED",cancelledAt:new Date(),cancellationReason:input.reason}});if(changed.count!==1)throw new AppError("CONFLICT","Ride changed while cancellation was being processed",409);await releaseRideFare(tx,{rideId:id,reason:`Rider cancellation: ${input.reason}`});if(existing.driverUserId)await tx.driveDriverProfile.updateMany({where:{userId:existing.driverUserId},data:{availability:"ONLINE"}});await tx.driveRideEvent.create({data:{rideId:id,type:"STATUS_CANCELLED",payload:{actorUserId:auth.userId,actor:"RIDER",reason:input.reason}}});return tx.driveRide.findUniqueOrThrow({where:{id}})});return{ride:rideContract(ride)}}requireNativeScope(auth, "drive.driver");if(existing.driverUserId!==auth.userId)throw new AppError("FORBIDDEN","Only the assigned driver can update this ride",403);if(input.status==="CANCELLED"){if(!["DRIVER_ASSIGNED","DRIVER_ARRIVING","DRIVER_ARRIVED","WAITING","RIDER_VERIFIED"].includes(existing.status))throw new AppError("CONFLICT","The driver cannot cancel this ride at its current stage",409);const penalty=await db.$transaction(async tx=>{const fee=await applyDriverPenalty(tx,{rideId:id,driverUserId:auth.userId,type:"CANCEL_AFTER_ACCEPT",rateBps:DRIVE_DRIVER_CANCEL_FEE_BPS,baseAmountMinor:existing.quote.totalMinor,reason:input.reason});await tx.driveDispatchOffer.updateMany({where:{rideId:id,driverUserId:auth.userId,status:"ACCEPTED"},data:{status:"CANCELLED",respondedAt:new Date()}});await tx.driveRide.update({where:{id},data:{driverUserId:null,status:"MATCHING",acceptedAt:null}});await tx.driveDriverProfile.update({where:{userId:auth.userId},data:{availability:"ONLINE"}});await tx.driveRideEvent.create({data:{rideId:id,type:"DRIVER_CANCELLED_AFTER_ACCEPT",payload:{driverUserId:auth.userId,reason:input.reason,feeBps:DRIVE_DRIVER_CANCEL_FEE_BPS,feeMinor:fee.toString()}}});return fee});await assignNearestDriver(id);return{ride:rideContract(await db.driveRide.findUniqueOrThrow({where:{id}})),driverCancellationFeeMinor:safeMinor(penalty),findingAnotherDriver:true}}assertDriverTransition(existing.status,input.status);if(input.status==="RIDER_VERIFIED"&&(!input.riderPin||!constantTimeStringEqual(sha256Base64Url(input.riderPin),existing.riderPinHash)))throw new AppError("FORBIDDEN","Rider PIN is invalid",403);const rules=await currentDriveRules();let distance=0;let penalty=0n;if(input.status==="COMPLETED"){const drop=pickupPointFromJson(existing.quote.dropoff);if(!drop||!input.actualLocation)throw new AppError("CONFLICT","Drop-off coordinates are required",409);distance=haversineMeters(drop,input.actualLocation);if(distance>rules.dropoffGeofenceMeters&&!input.forceOutsideDropoff)throw new AppError("CONFLICT",`End Trip is locked until the driver reaches the confirmed drop-off area (${rules.dropoffGeofenceMeters}m geofence)`,409)}const now=new Date();const ride=await db.$transaction(async tx=>{if(input.status==="IN_PROGRESS"){if(!existing.fareHold||existing.fareHold.status!=="HELD")throw new AppError("CONFLICT","The rider fare is not securely funded",409);await securePlatformCharge(tx,{rideId:id,amountMinor:existing.quote.platformFeeMinor,currency:existing.quote.currency})}if(input.status==="COMPLETED"&&distance>rules.dropoffGeofenceMeters)penalty=await applyDriverPenalty(tx,{rideId:id,driverUserId:auth.userId,type:"DROPOFF_VIOLATION",rateBps:DRIVE_DROPOFF_VIOLATION_FEE_BPS,baseAmountMinor:existing.quote.totalMinor,reason:input.reason??`Completed ${distance}m from confirmed drop-off`,debitWallet:false});if(input.status==="COMPLETED")await settleRideFare(tx,{rideId:id,driverUserId:auth.userId,driverEarningsMinor:existing.quote.driverEarningsMinor,additionalPlatformMinor:penalty,currency:existing.quote.currency});const changed=await tx.driveRide.updateMany({where:{id,status:existing.status,driverUserId:auth.userId},data:{status:input.status,platformChargeSecuredAt:input.status==="IN_PROGRESS"?now:undefined,startedAt:input.status==="IN_PROGRESS"?now:undefined,completedAt:input.status==="COMPLETED"?now:undefined,settledAt:input.status==="COMPLETED"?now:undefined,fareFundingStatus:input.status==="COMPLETED"?"SETTLED":undefined,actualDropoffLatitude:input.status==="COMPLETED"?input.actualLocation?.latitude:undefined,actualDropoffLongitude:input.status==="COMPLETED"?input.actualLocation?.longitude:undefined,actualDropoffDistanceMeters:input.status==="COMPLETED"?distance:undefined,dropoffOverrideReason:input.status==="COMPLETED"&&input.forceOutsideDropoff?input.reason:undefined}});if(changed.count!==1)throw new AppError("CONFLICT","Ride changed while this update was being processed",409);if(input.status==="COMPLETED")await tx.driveDriverProfile.update({where:{userId:auth.userId},data:{availability:"ONLINE"}});await tx.driveRideEvent.create({data:{rideId:id,type:`STATUS_${input.status}`,payload:{actorUserId:auth.userId,actualLocation:input.actualLocation??null,dropoffDistanceMeters:input.status==="COMPLETED"?distance:null,outsideDropoffOverride:input.status==="COMPLETED"?input.forceOutsideDropoff:false,dropoffPenaltyMinor:penalty.toString()}}});await appendOutboxEvent(tx,{aggregateType:"DriveRide",aggregateId:id,eventType:`drive.ride.${input.status.toLowerCase()}`,payload:{rideId:id,actorUserId:auth.userId,status:input.status}});return tx.driveRide.findUniqueOrThrow({where:{id}})},{isolationLevel:Prisma.TransactionIsolationLevel.Serializable});return{ride:rideContract(ride),dropoffPenaltyMinor:safeMinor(penalty)}});
