 app.post("/v1/admin/drive/drivers/:userId/reconcile-wallet", async request => {
  const auth = await requirePermission(request, "payout.manage");
  const { userId } = z.object({ userId: z.string().min(1) }).parse(request.params);
  const before = await getDriverWalletReconciliation(userId);
  if (before.reconciled) return {
    wallet: {
      currency: before.currency,
      profileBalanceMinor: safeMinor(before.profileBalanceMinor),
      ledgerBalanceMinor: safeMinor(before.driveLedgerBalanceMinor),
      payWalletBalanceMinor: safeMinor(before.payWalletBalanceMinor),
      platformDebtMinor: safeMinor(before.platformDebtMinor),
      payoutAvailableMinor: safeMinor(before.payoutAvailableMinor),
      reconciled: true,
    },
    actionState: "ALREADY_DONE" as const,
  };
  const ledgerBalance = before.driveLedgerBalanceMinor;
  const profile = await db.$transaction(async (tx) => {
    const current = await tx.driveDriverProfile.findUnique({ where: { userId } });
    if (!current) throw new AppError("NOT_FOUND", "Driver profile not found", 404);
    const delta = ledgerBalance - current.walletBalanceMinor;
    const updated = await tx.driveDriverProfile.update({
      where: { userId },
      data: { walletBalanceMinor: ledgerBalance, platformDebtMinor: ledgerBalance < 0n ? -ledgerBalance : 0n },
    });
    await tx.driveDriverLedgerEntry.create({
      data: {
        driverUserId: userId,
        type: "RECONCILIATION_MIRROR",
        amountMinor: delta,
        balanceAfterMinor: ledgerBalance,
        metadata: { actorUserId: auth.userId, source: "LEDGER_SOURCE_OF_TRUTH" },
      },
    });
    return updated;
  }, { isolationLevel: Prisma.TransactionIsolationLevel.Serializable });
  await audit({
    actorUserId: auth.userId,
    action: "drive.driver-wallet.reconciled",
    resourceType: "DriveDriverProfile",
    resourceId: profile.id,
    requestId: request.id,
    ipAddress: request.ip,
    metadata: {
      beforeProfileMinor: safeMinor(before.profileBalanceMinor),
      ledgerMinor: safeMinor(before.driveLedgerBalanceMinor),
      actionState: "COMPLETED",
    },
  });
  const after = await getDriverWalletReconciliation(userId);
  return {
    wallet: {
      currency: after.currency,
      profileBalanceMinor: safeMinor(after.profileBalanceMinor),
      ledgerBalanceMinor: safeMinor(after.driveLedgerBalanceMinor),
      payWalletBalanceMinor: safeMinor(after.payWalletBalanceMinor),
      platformDebtMinor: safeMinor(after.platformDebtMinor),
      payoutAvailableMinor: safeMinor(after.payoutAvailableMinor),
      reconciled: after.reconciled,
    },
    actionState: "COMPLETED" as const,
  };
 });
